EXEC sys.sp_addextendedproperty @name=N'MS_Description', @value=N'[Important] [1 Appointment] One row is: One row per appointment version (a cancel or reschedule keeps the old row and adds a new one). Why: The booking. Drives the pre-visit eligibility and authorization work, and the no-show and lead-time numbers. Not needed for revenue metrics, so Important, not Mandatory.', @level0type=N'SCHEMA', @level0name=N'dbo', @level1type=N'TABLE', @level1name=N'appointment';
EXEC sys.sp_addextendedproperty @name=N'MS_Description', @value=N'[Mandatory] Internal identity ID. Every join and link between tables uses this, so the client''s number never has to be shown or masked in analytics. If the source does not send it: Generated by us', @level0type=N'SCHEMA', @level0name=N'dbo', @level1type=N'TABLE', @level1name=N'appointment', @level2type=N'COLUMN', @level2name=N'appointment_id';
EXEC sys.sp_addextendedproperty @name=N'MS_Description', @value=N'[Mandatory] The client organisation the row belongs to. If the source does not send it: Always set by us', @level0type=N'SCHEMA', @level0name=N'dbo', @level1type=N'TABLE', @level1name=N'appointment', @level2type=N'COLUMN', @level2name=N'tenant_id';
EXEC sys.sp_addextendedproperty @name=N'MS_Description', @value=N'[Mandatory] [RESTRICTED] The client''s own appointment ID. Restricted: used only to match the source system. If the source does not send it: Hash of patient, provider, date, time', @level0type=N'SCHEMA', @level0name=N'dbo', @level1type=N'TABLE', @level1name=N'appointment', @level2type=N'COLUMN', @level2name=N'appointment_number';
EXEC sys.sp_addextendedproperty @name=N'MS_Description', @value=N'[Mandatory] Billing entity. If the source does not send it: Client default', @level0type=N'SCHEMA', @level0name=N'dbo', @level1type=N'TABLE', @level1name=N'appointment', @level2type=N'COLUMN', @level2name=N'practice_id';
EXEC sys.sp_addextendedproperty @name=N'MS_Description', @value=N'[Mandatory] The patient. If the source does not send it: Hash of member ID', @level0type=N'SCHEMA', @level0name=N'dbo', @level1type=N'TABLE', @level1name=N'appointment', @level2type=N'COLUMN', @level2name=N'patient_id';
EXEC sys.sp_addextendedproperty @name=N'MS_Description', @value=N'[Mandatory] Visit date; sets the 3-day and 1-day check timing. If the source does not send it: None', @level0type=N'SCHEMA', @level0name=N'dbo', @level1type=N'TABLE', @level1name=N'appointment', @level2type=N'COLUMN', @level2name=N'appointment_date';
