EXEC sys.sp_addextendedproperty @name=N'MS_Description', @value=N'[Mandatory] When the row was loaded. If the source does not send it: Always set by us', @level0type=N'SCHEMA', @level0name=N'dbo', @level1type=N'TABLE', @level1name=N'encounter', @level2type=N'COLUMN', @level2name=N'loaded_at';
EXEC sys.sp_addextendedproperty @name=N'MS_Description', @value=N'[Important] [2 Encounter] One row is: One row per clinical or administrative document in the EMR (visit note, consent, advance notice, plan of care, result, letter, document pack): who, when, status, signatures. Never the content. Why: The metadata layer for documentation work. It lets agents chase unsigned notes, check what a note documents, prove a consent or order is on file, and track which documents go with an authorization request or claim. Versioned: each change in status or signature is a new row, so signature lag and late entries can be measured as they were known.', @level0type=N'SCHEMA', @level0name=N'dbo', @level1type=N'TABLE', @level1name=N'document';
EXEC sys.sp_addextendedproperty @name=N'MS_Description', @value=N'[Mandatory] Internal identity ID. Every join and link between tables uses this, so the client''s number never has to be shown or masked in analytics. If the source does not send it: Generated by us', @level0type=N'SCHEMA', @level0name=N'dbo', @level1type=N'TABLE', @level1name=N'document', @level2type=N'COLUMN', @level2name=N'document_id';
EXEC sys.sp_addextendedproperty @name=N'MS_Description', @value=N'[Mandatory] The client organisation the row belongs to. If the source does not send it: Always set by us', @level0type=N'SCHEMA', @level0name=N'dbo', @level1type=N'TABLE', @level1name=N'document', @level2type=N'COLUMN', @level2name=N'tenant_id';
EXEC sys.sp_addextendedproperty @name=N'MS_Description', @value=N'[Mandatory] [RESTRICTED] The EMR''s own ID for the note or document. Makes loads repeatable. Restricted. If the source does not send it: Hash of encounter, document type and start date', @level0type=N'SCHEMA', @level0name=N'dbo', @level1type=N'TABLE', @level1name=N'document', @level2type=N'COLUMN', @level2name=N'document_number';
EXEC sys.sp_addextendedproperty @name=N'MS_Description', @value=N'[Important] Reports by practice. If the source does not send it: From the encounter', @level0type=N'SCHEMA', @level0name=N'dbo', @level1type=N'TABLE', @level1name=N'document', @level2type=N'COLUMN', @level2name=N'practice_id';
EXEC sys.sp_addextendedproperty @name=N'MS_Description', @value=N'[Important] Which patient''s chart. Hashed identity only. If the source does not send it: From the encounter', @level0type=N'SCHEMA', @level0name=N'dbo', @level1type=N'TABLE', @level1name=N'document', @level2type=N'COLUMN', @level2name=N'patient_id';
EXEC sys.sp_addextendedproperty @name=N'MS_Description', @value=N'[Mandatory] Broad family: note, consent, notice, plan_of_care, order_document, referral_document, result, letter, pack. Lets agents ask for all notes or all consents. If the source does not send it: Derived from the document type', @level0type=N'SCHEMA', @level0name=N'dbo', @level1type=N'TABLE', @level1name=N'document', @level2type=N'COLUMN', @level2name=N'document_class';
EXEC sys.sp_addextendedproperty @name=N'MS_Description', @value=N'[Mandatory] Specific type: progress_note, procedure_note, consult, discharge, telephone, addendum, treatment_consent, telehealth_consent, financial_consent, release_of_information, advance_notice, lab_result, imaging_result, letter_of_medical_necessity, cover_note and so on. If the source does not send it: ''progress_note'' for any visit document', @level0type=N'SCHEMA', @level0name=N'dbo', @level1type=N'TABLE', @level1name=N'document', @level2type=N'COLUMN', @level2name=N'document_type';
EXEC sys.sp_addextendedproperty @name=N'MS_Description', @value=N'[Mandatory] Where the document stands: not_started, draft, pended, signed, locked, amended, entered_in_error; for consents and notices on_file, missing, expired, withdrawn; for results received, reviewed. Drives the chase list. If the source does not send it: Derived from the encounter''s note_status', @level0type=N'SCHEMA', @level0name=N'dbo', @level1type=N'TABLE', @level1name=N'document', @level2type=N'COLUMN', @level2name=N'document_status';
EXEC sys.sp_addextendedproperty @name=N'MS_Description', @value=N'[Important] The visit the document belongs to. Blank for a standing consent. If the source does not send it: Match on patient and document date', @level0type=N'SCHEMA', @level0name=N'dbo', @level1type=N'TABLE', @level1name=N'document', @level2type=N'COLUMN', @level2name=N'encounter_id';
EXEC sys.sp_addextendedproperty @name=N'MS_Description', @value=N'[Important] The authorization request the document supports (the supporting-information link). Blank otherwise. If the source does not send it: Blank', @level0type=N'SCHEMA', @level0name=N'dbo', @level1type=N'TABLE', @level1name=N'document', @level2type=N'COLUMN', @level2name=N'authorization_id';
EXEC sys.sp_addextendedproperty @name=N'MS_Description', @value=N'[Important] The claim the document supports, for attachments and records requests. Blank otherwise. If the source does not send it: Blank', @level0type=N'SCHEMA', @level0name=N'dbo', @level1type=N'TABLE', @level1name=N'document', @level2type=N'COLUMN', @level2name=N'claim_id';
EXEC sys.sp_addextendedproperty @name=N'MS_Description', @value=N'[Important] The clinician who wrote or signed it (internal provider, never a name). If the source does not send it: Rendering provider of the encounter', @level0type=N'SCHEMA', @level0name=N'dbo', @level1type=N'TABLE', @level1name=N'document', @level2type=N'COLUMN', @level2name=N'author_provider_id';
EXEC sys.sp_addextendedproperty @name=N'MS_Description', @value=N'[Optional] Role of the signer: physician, nurse_practitioner, physician_assistant, resident, therapist, other. Supervision and incident-to rules depend on it. If the source does not send it: Blank; read from the provider''s credential', @level0type=N'SCHEMA', @level0name=N'dbo', @level1type=N'TABLE', @level1name=N'document', @level2type=N'COLUMN', @level2name=N'signer_role';
EXEC sys.sp_addextendedproperty @name=N'MS_Description', @value=N'[Important] Date the document was started (note date, consent date). Late entries are measured against the visit date. If the source does not send it: Encounter date', @level0type=N'SCHEMA', @level0name=N'dbo', @level1type=N'TABLE', @level1name=N'document', @level2type=N'COLUMN', @level2name=N'document_date';
EXEC sys.sp_addextendedproperty @name=N'MS_Description', @value=N'[Important] Date and time of the signature. Signature lag and the time of day a note is signed. If the source does not send it: Encounter.note_signed_date at 00:00', @level0type=N'SCHEMA', @level0name=N'dbo', @level1type=N'TABLE', @level1name=N'document', @level2type=N'COLUMN', @level2name=N'signed_at';
EXEC sys.sp_addextendedproperty @name=N'MS_Description', @value=N'[Important] 1 if written well after the visit. Payers question late notes. If the source does not send it: Signed date minus visit date over the practice''s late-entry limit', @level0type=N'SCHEMA', @level0name=N'dbo', @level1type=N'TABLE', @level1name=N'document', @level2type=N'COLUMN', @level2name=N'is_late_entry';
EXEC sys.sp_addextendedproperty @name=N'MS_Description', @value=N'[Important] 1 if this row is a later addition to a signed note. The date of the addendum is its signed_at. If the source does not send it: document_type = addendum', @level0type=N'SCHEMA', @level0name=N'dbo', @level1type=N'TABLE', @level1name=N'document', @level2type=N'COLUMN', @level2name=N'is_addendum';
EXEC sys.sp_addextendedproperty @name=N'MS_Description', @value=N'[Optional] The original note this addendum adds to. If the source does not send it: Blank', @level0type=N'SCHEMA', @level0name=N'dbo', @level1type=N'TABLE', @level1name=N'document', @level2type=N'COLUMN', @level2name=N'addendum_of_document_id';
EXEC sys.sp_addextendedproperty @name=N'MS_Description', @value=N'[Optional] 1 if the document is locked and cannot be edited. A locked unsigned note is a different fix. If the source does not send it: Status = locked', @level0type=N'SCHEMA', @level0name=N'dbo', @level1type=N'TABLE', @level1name=N'document', @level2type=N'COLUMN', @level2name=N'is_locked';
EXEC sys.sp_addextendedproperty @name=N'MS_Description', @value=N'[Important] 1 if a second signature is needed (supervision rule). If the source does not send it: Derived from signer role and payer rule; blank if unknown', @level0type=N'SCHEMA', @level0name=N'dbo', @level1type=N'TABLE', @level1name=N'document', @level2type=N'COLUMN', @level2name=N'cosign_required';
EXEC sys.sp_addextendedproperty @name=N'MS_Description', @value=N'[Optional] not_needed, pending or done. If the source does not send it: Blank when cosign_required is blank', @level0type=N'SCHEMA', @level0name=N'dbo', @level1type=N'TABLE', @level1name=N'document', @level2type=N'COLUMN', @level2name=N'cosign_status';
