EXEC sys.sp_addextendedproperty @name=N'MS_Description', @value=N'[Important] List of named elements found in the note (chief_complaint, history_present, exam, assessment, plan, diagnosis_linked, procedure_note, laterality, result, medical_necessity, mdm, telehealth_statements). Codes only, never text. The count goes on the encounter. If the source does not send it: Blank; encounter.elements_documented count only', @level0type=N'SCHEMA', @level0name=N'dbo', @level1type=N'TABLE', @level1name=N'document', @level2type=N'COLUMN', @level2name=N'elements_documented';
