EXEC sys.sp_addextendedproperty @name=N'MS_Description', @value=N'[Optional] Number of body systems reviewed; supports the code-level check. If the source does not send it: Blank', @level0type=N'SCHEMA', @level0name=N'dbo', @level1type=N'TABLE', @level1name=N'document', @level2type=N'COLUMN', @level2name=N'ros_system_count';
